item.aggregated_output:
	\leq& O(\delta_S + \eps).
\end{align*}
\Cref{eq:qld-sg-cons2} is thus obtained by absorbing $\eps$ into the function $\delta_S$.  
\end{proof}


 The next lemma shows that we can construct local unitaries $V_A,V_B$ from the measurements $\hat{S}$  such that the shared state $\ket{\hat{\psi}}$ is close to $\ket{\aux} \otimes \ket{\EPR_q}^{\otimes \nqubits}$ for some state $\ket{\aux}$, and the observables $\tilde{W}^j(\tilde{u})$ are mapped to Pauli observables $\tau^W(e_j \tilde{u})$ acting on $\ket{\EPR_q}^{\otimes \nqubits}$. Using the consistency between the $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ measurements and the points measurements $\{M^{(\Point,W),u}_a\}_{a \in \F_q}$ established in \Cref{lem:qld-construct-the-paulis}, and the consistency between the points measurements and the ``total Pauli measurements'' $\{M^{(\Pauli,W)}_h\}_{h \in \F_q^\nqubits}$ established in \Cref{lem:qld-win-implications}, we deduce that the total Pauli measurements must be close (up to the local unitaries $V_A,V_B$) to the Pauli projectors $\{\tau^W_h\}_{h \in \F_q^\nqubits}$ acting on $\ket{\EPR_q}^{\otimes \nqubits}$.


\begin{lemma}
\label{lem:qld-unitary}
There exists a function $\delta_\qld(\eps,m,d,q) = O(\delta_S^{1/4} + md/q)$ (where $\delta_S$ is defined in \Cref{lem:qld-4-7}) and unitaries $V_\alice$ acting on registers $\alice \alice' \alice''$ and $V_\bob$ acting on $\bob \bob' \bob''$ such that 
\begin{enumerate}
	\item There exists a state $\ket{\aux}$ on registers $\alice \alice' \bob \bob'$ such that
	\[
		\left \| V_\alice \otimes V_\bob \ket{\hat{\psi}}_{\alice \alice' \alice'' \bob \bob' \bob''} - \ket{\aux}_{\alice \alice' \bob \bob'} \otimes \ket{\EPR_q}^{\otimes \nqubits}_{\alice'' \bob''} \right \|^2 \leq \delta_\qld.
	\]

	\item For all $W \in \{X,Z\}, h \in \F_q^\nqubits$
	\begin{align*}
		V_\alice \, \Big(M^{(\Pauli,W)}_h \Big)_{\alice} \, V_\alice^\dagger &\approx_{\delta_\qld} \Id_{\alice \alice'} \otimes (\tau^W_h)_{\alice''} \\
		 V_\bob \, \Big(M^{(\Pauli,W)}_h  \Big)_{\bob}\, V_\bob^\dagger &\approx_{\delta_\qld} \Id_{\bob \bob'} \otimes (\tau^W_h)_{\bob''}
	\end{align*}
	where the $\approx$ statements hold with respect to the state $\ket{\aux}_{\alice \alice' \bob \bob'} \otimes \ket{\EPR_q}^{\otimes \nqubits}_{\alice'' \bob''}$. 
\end{enumerate}
\end{lemma}

\begin{proof}

Define the linear map
\[
	V_\alice = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\alice \alice'} \otimes (\tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)))_{\alice ''}\;,
\]
where the $\tau^X(\cdot),\tau^Z(\cdot)$ act on $(\C^q)^{\otimes \nqubits}$. (Also note that the argument of $\tau^X$ is $\coded(g_Z)$ and the argument of $\tau^Z$ is $\coded(g_X)$.) We verify the unitarity of $V_\alice$:
\begin{align*}
	V_\alice V_\alice^\dagger &= \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\alice \alice'} \otimes (\tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)) \tau^Z(\coded(g_X)) \tau^X(\coded(g_Z)) )_{\alice ''} \\
	&= \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\alice \alice'} \otimes \Id_{\alice ''} \\
	&= \Id_{\alice \alice' \alice''}
\end{align*}
where in the first line we used that the measurement $\{ \hat{S}_{g_\xpt,g_\zpt} \}$  is projective and in the second line we used that the $\tau^Z$ and $\tau^X$ observables are self-inverse. The unitary $V_\bob$ is defined analogously.

Let $\{e_j\}_{j \in \{1,\ldots,t\}}$ denote the self-dual basis for $\F_q$ over $\F_2$ specified in \Cref{sec:subfields}, and let $\tilde{W}^j$ be the observables introduced in~\eqref{eq:def-tildewj}. Conjugating the observable $\tilde{W}^j$ acting on the registers $\alice \alice' \alice''$ by the unitary $V_\alice$ we get
\begin{align*}
	&V_\alice \, \tilde{W}^j(\tilde{u}) \, V_\alice^\dagger \\
  =& \sum_{g_X, g_Z} (-1)^{\tr( e_j(\coded(g_W) \cdot \tilde{u}))} \Big( \hat{S}_{g_X,g_Z}  \Big)_{\alice \alice'} \otimes \Big ( \tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)) \tau^W(e_j \tilde{u}) \\
  &\hspace{24em}\tau^Z(\coded(g_X))^\dagger \tau^X(\coded(g_Z))^\dagger \Big)_{\alice ''} \\
	 =& \sum_{g_X, g_Z} \Big( \hat{S}_{g_X,g_Z}  \Big)_{\alice \alice'} \otimes \Big ( \tau^W(e_j \tilde{u}) \Big)_{\alice ''} \\
	 =& \Id_{\alice \alice'} \otimes \Big( \tau^W(e_j \tilde{u}) \Big)_{\alice ''}\;,
\end{align*}
where in the third line we used the (anti-)commutation relation
\[
	\tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)) \tau^W(e_j \tilde{u}) = (-1)^{\tr( e_j(\coded(g_W) \cdot \tilde{u}))} \tau^W(e_j \tilde{u}) \tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)) \;.
\]
An entirely analogous calculation shows that $V_\bob \, \tilde{W}^j(\tilde{u}) \, V_\bob^\dagger = \Id_{\bob \bob'} \otimes \Big( \tau^W(e_j \tilde{u}) \Big)_{\bob ''}$.

Next, from the self-consistency property of the observables $\tilde{W}^j$ specified in \Cref{lem:qld-construct-the-paulis} we get that for $W \in \{X,Z\}$,
\[
	\E_{j \in \{1,\ldots,t\}} \E_{\tilde{u} \in \F_q^\nqubits} \bra{\hat{\psi}} \left ( \tilde{W}^j(\tilde{u}) \otimes \Id - \Id \otimes \tilde{W}^j(\tilde{u}) \right)^\dagger \left ( \tilde{W}^j(\tilde{u}) \otimes \Id - \Id \otimes \tilde{W}^j(\tilde{u}) \right) \ket{\hat{\psi}} \leq \delta_S\;,
\]
which, since $\tilde{W}^j$ is Hermitian, is equivalent to
\begin{equation}
\label{eq:qld-unitary-1}
\E_{j \in \{1,\ldots,t\}} \E_{\tilde{u} \in \F_q^\nqubits} \bra{\hat{\psi}} \tilde{W}^j(\tilde{u}) \otimes \tilde{W}^j(\tilde{u}) \ket{\hat{\psi}} \geq 1 - \delta_S/2\;.
\end{equation}
Let $\ket{\vartheta} = V_\alice \otimes V_\bob \ket{\hat{\psi}}$, and for $W \in \{X,Z\}$ define the operator
\begin{align*}
	H_W &= \E_{j \in \{1,\ldots,t\}} \E_{\tilde{u} \in \F_q^\nqubits} \tau^W(e_j \tilde{u}) \otimes \tau^W(e_j \tilde{u}) \\
		&= \E_{j \in \{1,\ldots,t\}} \Big ( \E_{s \in \F_q} \tau^W(e_j s) \otimes \tau^W(e_j s) \Big)^{\otimes \nqubits} \\
		&= \Big ( \E_{s \in \F_q} \tau^W(s) \otimes \tau^W(s) \Big)^{\otimes \nqubits}
\end{align*}
where in the second line we used that for all $\tilde{u} \in \F_q^\nqubits$, $\tau^W(\tilde{u}) = \bigotimes_{i = 1}^\nqubits \tau^W(\tilde{u}_i)$ with $\tau^W(\tilde{u}_i)$ being the generalized Pauli $W$ observable acting on the $i$-th qudit. In the third line, we used the fact that for every fixed $j$, we have $\E_{s \in \F_q} \tau^W(e_j s) \otimes \tau^W(e_j s) = \E_{s \in \F_q} \tau^W(s) \otimes \tau^W(s)$. \Cref{eq:qld-unitary-1} is then equivalent to 
\[
	\bra{\vartheta} H_W \ket{\vartheta} \geq 1 - \delta_S/2\;,
\]
for $W \in \{X,Z\}$. 

Observe that
\begin{align*}
	\E_{s,s'} \tau^X(s) \tau^Z(s') \otimes \tau^X(s) \tau^Z(s') &= \E_{s,s'} \sum_{a,b \in \F_q} (-1)^{\tr(as')} \ketbra{a+s}{a} \otimes (-1)^{\tr(bs')} \ketbra{b+s}{b} \\
	&= \E_{s} \sum_{a\in \F_q} \ketbra{a+s}{a} \otimes \ketbra{a+s}{a} \\
	&= \proj{\EPR_q}
\end{align*}
where to go from the first to the second line we used \Cref{lem:cancellation}. This implies that $H_X H_Z = \Big ( \E_{s,s' \in \F_q} \tau^X(s)\tau^Z(s') \otimes \tau^X(s)\tau^Z(s') \Big)^{\otimes \nqubits} = \ketbra{\EPR_q}{\EPR_q}^{\otimes \nqubits}$.
By the triangle inequality, we have
\[
	\left \| H_X \ket{\vartheta} - H_Z \ket{\vartheta} \right\| \leq \left \| \ket{\vartheta} - H_X \ket{\vartheta} \right\| + \left \| \ket{\vartheta} - H_Z \ket{\vartheta} \right\|\;.
\]
Note that for $W \in \{X,Z\}$,
\[
	\left \| \ket{\vartheta} - H_W \ket{\vartheta} \right\|^2 = 1 - 2\bra{\vartheta} H_W \ket{\vartheta} + \bra{\vartheta} H_W^2 \ket{\vartheta} \leq 2 - 2\bra{\vartheta} H_W \ket{\vartheta} \leq \delta_S\;,
\]
where in the inequality we used that $H_W \leq \Id$. Furthermore,
\begin{align*}
	\bra{\vartheta} H_W^2 \ket{\vartheta} &=\| H_W \ket{\vartheta} \|^2\\
	 &= \| \ket{\vartheta} + (H_W - \Id) \ket{\vartheta} \|^2 \\
	 &\geq (\|\ket{\vartheta}\| - \| (H_W - \Id) \ket{\vartheta} \|)^2 \\
	 &\geq (1 - \delta_S)^2 \\
	 &\geq 1 - 2\delta_S\;. 
\end{align*}
Therefore 
\begin{align*}
2\sqrt{\delta_S} &\geq \left \| H_X \ket{\vartheta} - H_Z \ket{\vartheta} \right\|^2  \\
&= \bra{\vartheta} H_X^2 \ket{\vartheta} + \bra{\vartheta} H_Z^2 \ket{\vartheta} - 2\bra{\vartheta} H_X H_Z \ket{\vartheta} \\
&\geq 2 - 4\delta_S - 2\bra{\vartheta} H_X H_Z \ket{\vartheta} \;,
\end{align*}
which implies that 
\[
	\bra{\vartheta} (\Id_{\alice \alice' \bob \bob'} \otimes (\proj{\EPR_q}^{\otimes \nqubits})_{\alice'' \bob''}) \ket{\vartheta} \geq 1 - 2\delta_S - \sqrt{\delta_S} \;.
\]
Define the unnormalized state $\ket{\aux_0}$ on the registers $\alice \alice' \bob \bob'$ as
\[
	\ket{\aux_0}_{\alice \alice' \bob \bob'} = (\bra{\EPR_q}^{\otimes \nqubits})_{\alice'' \bob''} \cdot \ket{\vartheta}_{\alice \alice' \alice'' \bob \bob' \bob''}
\]
and define the normalized state $\ket{\aux} = \frac{1}{\| \, \ket{\aux_0} \, \|} \ket{\aux_0}$. 
The inner product between $\ket{\vartheta}$ and $\ket{\aux} \otimes \ket{\EPR_q}^{\otimes \nqubits}$ can thus be evaluated as
\begin{align*}
	\bra{\vartheta} (\ket{\aux} \otimes \ket{\EPR_q}^{\otimes \nqubits}) &= \frac{1}{\| \, \ket{\aux_0} \, \|} \cdot \bra{\vartheta} (\ket{\aux_0} \otimes \ket{\EPR_q}^{\otimes \nqubits}) \\
	&= \frac{1}{\| \, \ket{\aux_0} \, \|} \cdot \bra{\vartheta} (\Id_{\alice \alice' \bob \bob'} \otimes (\proj{\EPR_q}^{\otimes \nqubits})_{\alice'' \bob''}) \ket{\vartheta} \\
	&= \frac{1}{\| \, \ket{\aux_0} \, \|} \cdot \| \, \ket{\aux_0} \, \|^2 \\
	&= \| \, \ket{\aux_0} \, \| \\
	&\geq \sqrt{1 - 2\delta_S - \sqrt{\delta_S}} \\
	&\geq 1 - O(\sqrt{\delta_S})\;.
\end{align*}
This implies $\| \ket{\vartheta} - \ket{\aux} \otimes \ket{\EPR_q}^{\otimes \nqubits} \|^2 \leq O(\sqrt{\delta_S})$, which establishes the first item of the lemma.

We now establish the second item of the lemma. In what follows, all $\simeq$ and $\approx$ statements hold with respect to the state $\ket{\hat{\psi}}$. From \Cref{lem:qld-win-implications} we have the following implications: for all $W \in \{X,Z\}$ and on average over $u \in \F_q^m$,
	\begin{align}
	\label{eq:qld-unitary-2}
	M^{(\Pauli,W)}_{[g_h(u)=a]} \otimes \Id_{\bob \bob' \bob''} &\simeq_\eps \Id_{\alice \alice' \alice''} \otimes M^{(\Point,W),u}_a\;, \\
	\label{eq:qld-unitary-3}
	\Id_{\alice \alice' \alice''} \otimes M^{(\Point,W),u}_a &\simeq_\eps  M^{(\Point,W),u}_a \otimes \Id_{\bob \bob' \bob''}\;,
	\end{align}
	where $M^{(\Pauli,W)}_{[g_h(u)=a]} = \sum_{h : g_h(u) = a} M^{(\Pauli,W)}_h$. 
From \Cref{lem:qld-construct-the-paulis} we get that
	\begin{equation}
	\label{eq:qld-unitary-4}

	\label{eq:qld-unitary-4}
		M^{(\Point,W),u}_a \otimes \Id_{\bob \bob' \bob''} \simeq_{\delta_S} \Id_{\alice \alice' \alice''}  \otimes \tilde{M}^{W,\ind_m(u)}_a\;.
	\end{equation}
Using \Cref{fact:triangle-for-simeq} with Equations \eqref{eq:qld-unitary-2}, \eqref{eq:qld-unitary-3}, and \eqref{eq:qld-unitary-4}, we get 
	\begin{equation}
		\label{eq:qld-unitary-5}
		M^{(\Pauli,W)}_{[g_h(u)=a]} \otimes \Id_{\bob \bob' \bob''} \simeq_{\sqrt{\delta_S}} \Id_{\alice \alice' \alice''}  \otimes \tilde{M}^{W,\ind_m(u)}_a\;,
	\end{equation}
	where we used that $\delta_S \geq \eps$. 

	Next, we have for all $u \in \F_q^m$ 
	\begin{align}
		&V_\bob \, \tilde{M}^{W,\ind_m(u)}_a \, V_\bob^\dagger \notag \\
		= &\sum_{g_X, g_Z} \Big( \hat{S}_{g_X,g_Z}  \Big)_{\bob \bob'} \otimes \Big ( \tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)) \tau^W_{g_W(u) - a}(\ind_m(u))    \tau^Z(\coded(g_X))^\dagger \tau^X(\coded(g_Z))^\dagger \Big)_{\bob ''} \notag \\
		= &\sum_{g_X, g_Z} \Big( \hat{S}_{g_X,g_Z}  \Big)_{\bob \bob'} \otimes \sum_{h : g_h(u) = g_W(u) - a} \Big ( \tau^X(\coded(g_Z)) \tau^Z(\coded(g_X)) \tau^W_h   \tau^Z(\coded(g_X))^\dagger \tau^X(\coded(g_Z))^\dagger \Big)_{\bob ''} \notag \\
		= &\sum_{g_X, g_Z} \Big( \hat{S}_{g_X,g_Z}  \Big)_{\bob \bob'} \otimes \sum_{h : g_h(u) = g_W(u) - a} \Big ( \tau^W_{h + \coded(g_W)}   \Big)_{\bob ''} \notag \\
	= &\sum_{g_X, g_Z} \Big( \hat{S}_{g_X,g_Z}  \Big)_{\bob \bob'} \otimes \sum_{h : g_h(u) = a} \Big ( \tau^W_{h}   \Big)_{\bob ''} \notag \\
= &\Id_{\bob \bob'} \otimes (\tau^W_{[g_h(u)=a]})_{\bob''}\;,		\label{eq:qld-unitary-6}
	\end{align}
	where in the second line we expanded out the definitions of $V_\bob$ and $\tilde{M}^{W,\ind_m(u)}_a$ (defined in \cref{eq:tilde_M}); in the third line we expanded out the definition of $\tau^W_{g_W(u) - a}(\ind_m(u))$ (defined in \cref{eq:def-tauwu}) and used the fact that for all $h \in \F_q^M$, the inner product $h \cdot \ind_m(u)$ is equal to $g_h(u)$; in the fourth line we used the identities
	\[
		\tau^X(s) \tau^Z_h \tau^X(s)^\dagger = \tau^Z_{h + s} \qquad \text{and} \qquad \tau^Z(s) \tau^X_h \tau^Z(s)^\dagger = \tau^X_{h + s}~;
	\]
	and in the fifth line is due to the following short calculation: for all fixed $g_W$ we have
	\begin{align*}
		\sum_{h : g_h(u) = g_W(u) - a}  \tau^W_{h + \coded(g_W)} = \sum_{h: g_W(u) - g_h(u) = a} \tau^W_{h + \coded(g_W)} = \sum_{h: g_W(u) + g_h(u) = a} \tau^W_{h + \coded(g_W)} = \sum_{h': g_{h'}(u) = a} \tau^W_{h'}~.
	\end{align*}
	The second equality from the fact that $\F_q$ is a field of characteristic $2$ (so subtraction is the same as addition), and the third equality follows from the fact that letting $h' = h + \coded(g_W)$, we have $g_{h'} = g_h + g_W$ (in other words, the low-degree encoding $h \mapsto g_h$ is linear in $h$). 




Let $\ket{\Delta} = \ket{\aux} \otimes \ket{\EPR_q}^{\otimes \nqubits}$. We show that $V_\alice \, \Big(M^{(\Pauli,W)}_h \Big)_{\alice} \, V_\alice^\dagger \approx_{\delta_\qld} \Id_{\alice \alice'} \otimes (\tau^W_h)_{\alice''}$ (the argument for the operators acting on registers $\bob \bob' \bob''$ proceeds identically). 
	\begin{align}
		&\sum_h \bra{\Delta} \left ( V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger - (\tau^W_h)_{\alice''}  \right)^\dagger \left ( V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger - (\tau^W_h)_{\alice''} \right) \ket{\Delta} \notag \\
		&= 2 - 2 \Re \, \sum_h \bra{\Delta} V_\alice\, M^{(\Pauli,W)}_h \, V_\alice^\dagger  \, (\tau^W_h)_{\alice''} \ket{\Delta} \notag \\
		&= 2 - 2 \, \sum_h \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger  \, \otimes (\tau^W_h)_{\bob''} \ket{\Delta} \label{eq:qld-unitary-7}
\end{align}
	where in the last line we used that $(\tau^W_h)_{\alice''} \ket{\EPR_q}^{\otimes \nqubits} = (\tau^W_h)_{\bob''} \ket{\EPR_q}^{\otimes \nqubits}$.
	We now claim that
	\begin{align}
	&  \, \sum_h \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger  \, \otimes (\tau^W_h)_{\bob''} \ket{\Delta}  \notag \\
	&\approx_{md/q}  \E_u \sum_{\substack{h, h' : \\ g_h(u) = g_{h'}(u)}} \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger  \, \otimes (\tau^W_{h'})_{\bob''} \ket{\Delta} \label{eq:qld-unitary-8} \\
	&=  \E_u \sum_{a \in \F_q} \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_{[g_h(u)=a]} \, V_\alice^\dagger \, \otimes (\tau^W_{[g_h(u)=a]})_{\bob''} \ket{\Delta} \notag \\
	&=  \E_u \sum_{a \in \F_q} \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_{[g_h(u)=a]} \, V_\alice^\dagger \, \otimes V_\bob  \, \tilde{M}^{W,\ind_m(u)}_a \, V_\bob^\dagger \ket{\Delta} \label{eq:qld-unitary-9}
	\end{align}
	where the equality in \Cref{eq:qld-unitary-9} follows from the identity in \Cref{eq:qld-unitary-6}, and the approximation in \Cref{eq:qld-unitary-8} follows from the following calculation:
	\begin{align*}
		& \E_u \sum_{\substack{h \neq h' : \\ g_h(u) = g_{h'}(u)}} \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger  \, \otimes (\tau^W_{h'})_{\bob''} \ket{\Delta}  \\
		&= \sum_{h \neq h'} \left( \E_u \mathbf{1}[g_h(u) = g_{h'}(u)] \right) \bra{\Delta} V_\alice \, M^{(\Pauli,W)}_h \, V_\alice^\dagger  \, \otimes (\tau^W_{h'})_{\bob''} \ket{\Delta} \\
		&\leq \frac{md}{q}\;.
	\end{align*}
	In the last line we used that for for distinct $h \neq h'$, the polynomials $g_h \neq g_{h'}$ and thus by the Schwartz-Zippel lemma can only agree on at most $md/q$ fraction of points $u \in \F_q^m$. 

	Continuing from \Cref{eq:qld-unitary-9}, we use the first item of the Lemma which shows that $\| \ket{\Delta} - \ket{\vartheta} \|^2 \leq O(\sqrt{\delta_S})$ and equivalently $\| V_\alice^\dagger \otimes V_\bob^\dagger \ket{\Delta} - \ket{\hat{\psi}} \|^2 \leq O(\sqrt{\delta_S})$, so 
	\begin{align*}
		\text{\cref{eq:qld-unitary-9}} &\approx_{O(\delta_S^{1/4})} \E_u \sum_{a \in \F_q} \bra{\hat{\psi}} M^{(\Pauli,W)}_{[g_h(u)=a]} \otimes \tilde{M}^{W,\ind_m(u)}_a \ket{\hat{\psi}} \\
		&\geq 1 - O(\delta_S^{1/2})\;,
	\end{align*}
        where the last line comes from \eqref{eq:qld-unitary-5}.
	Together with \Cref{eq:qld-unitary-7}, 
	\[
	\text{\cref{eq:qld-unitary-7}} \leq O(\delta_S^{1/4} + md/q)\;.	
	\]

	Schwartz--Zippel; it is not an additional extraction hypothesis.
\end{lemma}

% Following the source, the next lemma is stated after
% lem:qld-construct-the-paulis, whose proof invokes it; its own proof
% depends only on lem:qld-4-7 and lem:qld-comm-cons, so there is no
% circularity.
Lemmas~\ref{lem:qld-4-7} and~\ref{lem:qld-comm-cons} imply the following two estimates, which were used in the proof of Lemma~\ref{lem:qld-construct-the-paulis}.

\begin{lemma}[The marginals absorb the point measurements]\label{lem:qld-constructing-the-paulis-helper}
	\lean{MIPStarRE.QPBT.sum_marginalPoly_pointMeas_approx_id}
	\lean{MIPStarRE.QPBT.marginalPoly_sub_pointMeas_approx_zero}
	\leanok
	\uses{def:s-w-marginals, def:expanded-point-measurement, def:expanded-state, def:povm-distance, lem:qld-4-7, def:symmetric-equivalents}
	For $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
	\begin{equation}\label{eq:qld-sg-cons}
		\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P^{\mathrm{id}}} \Id
	\end{equation}
	and
	\begin{equation}\label{eq:qld-sg-cons2}
		\bigl(\hat{S}^W_g \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)})\bigr)_{\mathrm{A}\mathrm{A}'} \approx_{\delta_P^{\mathrm{ann}}} 0\;,
	\end{equation}
	where the answer summation is over $g \in \mathrm{ideg}_{d,m}(\F_q)$. The independently quantified scale $\delta_P^{\mathrm{ann}}$ includes the additional point-measurement error in \eqref{eq:qld-sg-cons2}. Furthermore, all symmetric equivalents of these approximations also hold (Definition~\ref{def:symmetric-equivalents}).
\end{lemma}
\begin{proof}
	\uses{lem:qld-4-7, fact:agreement, fact:add-a-proj, def:bracket, lem:qld-comm-cons}
	The point-consistency conclusion of Lemma~\ref{lem:qld-4-7} states that, on average over $u \in \F_q^m$,
	\[
		\bra{\hat\psi} \sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point}, W), u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \ket{\hat\psi} \geq 1 - \delta_G\;,
	\]
	which says exactly that the operator on the left-hand side of \eqref{eq:qld-sg-cons} is $\delta_G$-consistent with $\Id$; Lemma~\ref{fact:agreement} and the universal-factor enlargement give the $\approx_{\delta_P}$ statement \eqref{eq:qld-sg-cons}. For \eqref{eq:qld-sg-cons2}, the same consistency, written with the coarse-graining $\hat{S}^W_{[g(u)=a]} = \sum_{g : g(u) = a} \hat{S}^W_g$ as $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G)} (\hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{B}\mathrm{A}''}$ with answer summation over $a \in \F_q$, is left-multiplied by $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'}$ using Lemma~\ref{fact:add-a-proj}; moving $\hat{M}^{(\mathrm{Point}, W), u}_a$ from registers $\mathrm{B}\mathrm{A}''$ to $\mathrm{A}\mathrm{A}'$ costs a further $\eps$ by Cauchy--Schwarz together with the self-consistency of the $\hat{M}^{(\mathrm{Point}, W), u}_a$ (Lemma~\ref{lem:qld-comm-cons}), giving
	\[
		(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G + \eps)} (\hat{S}^W_{[g(u)=a]} \cdot \hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{A}\mathrm{A}'}\;.
	\]
	Expanding
	\[
		\E_u \sum_g \bigl\| (\hat{S}^W_{g} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)}))_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi} \bigr\|^2
		= \E_u \sum_a \bra{\hat\psi} \bigl((\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a}) \cdot \hat{S}^W_{[g(u)=a]} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a})\bigr)_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi}
	\]
	and bounding the right-hand side by $O(\delta_G + \eps)$ using the two approximations above yields \eqref{eq:qld-sg-cons2} at scale $\delta_P$. The symmetric equivalents follow by the same argument with the register bipartitions interchanged.
\end{proof}

\section{The swap unitaries and the extraction of the Pauli group}

\begin{definition}[The swap unitaries]\label{def:v-swap-unitary}
	\lean{MIPStarRE.QPBT.swapUnitary}
	\leanok
	\uses{lem:qld-4-7, def:generalized-pauli, def:qld-full-field-decoder}
	Define the linear map
	\[
		V_{\mathrm{A}} = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \bigl(\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))\bigr)_{\mathrm{A}''}\;,
	\]
	where $\tau^X(\cdot)$ and $\tau^Z(\cdot)$ are the generalized Pauli observables acting on $(\C^q)^{\ot M}$; note that the argument of $\tau^X$ is $\mathrm{Dec}(g_Z)$ and the argument of $\tau^Z$ is $\mathrm{Dec}(g_X)$. The map $V_{\mathrm{B}}$, acting on registers $\mathrm{B}\mathrm{B}'\mathrm{B}''$, is defined analogously.
\end{definition}

% In the source the following properties are established inline with the
% definition of the swap unitaries; they are recorded here as a lemma.
\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
	\lean{MIPStarRE.QPBT.swapUnitary_mul_conjTranspose}
	\lean{MIPStarRE.QPBT.conjTranspose_mul_swapUnitary}
	\lean{MIPStarRE.QPBT.swapUnitary_conj_tildeObs}
	\lean{MIPStarRE.QPBT.swapUnitary_conj_tildeM}
	\leanok
	\uses{def:v-swap-unitary, def:tilde-w-observables, def:tilde-m-measurement, def:generalized-pauli, def:indicator-vector, def:bracket}
	The maps $V_{\mathrm{A}}$ and $V_{\mathrm{B}}$ of Definition~\ref{def:v-swap-unitary} are unitaries acting on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ and $\mathrm{B}\mathrm{B}'\mathrm{B}''$ respectively, and their conjugation action is exact, as follows. For all $W \in \{X,Z\}$, $j \in \{0,\ldots,t-1\}$, and $\tilde{u} \in \F_q^M$,
	\begin{equation}\label{eq:v-swap-obs-conjugation}
		V_{\mathrm{A}} \, \tilde{W}^j(\tilde{u}) \, V_{\mathrm{A}}^\dagger = \Id_{\mathrm{A}\mathrm{A}'} \ot \bigl( \tau^W(e_j \tilde{u}) \bigr)_{\mathrm{A}''}
		\qquad \text{and} \qquad
		V_{\mathrm{B}} \, \tilde{W}^j(\tilde{u}) \, V_{\mathrm{B}}^\dagger = \Id_{\mathrm{B}\mathrm{B}'} \ot \bigl( \tau^W(e_j \tilde{u}) \bigr)_{\mathrm{B}''}\;,
	\end{equation}
	and for all $W \in \{X,Z\}$, $u \in \F_q^m$, and $a \in \F_q$,
	\begin{equation}\label{eq:qld-unitary-6}
		V_{\mathrm{B}} \, \tilde{M}^{W,\mathrm{ind}_m(u)}_a \, V_{\mathrm{B}}^\dagger = \Id_{\mathrm{B}\mathrm{B}'} \ot (\tau^W_{[g_h(u)=a]})_{\mathrm{B}''}\;,
		\qquad
		\tau^W_{[g_h(u)=a]} = \sum_{h \,:\, g_h(u) = a} \tau^W_h\;,
	\end{equation}
	together with the analogous identity for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$.
\end{lemma}
\begin{proof}
	\uses{lem:qld-4-7, lem:tildew-product-form, lem:twisted-commutation, def:v-swap-unitary, def:tilde-m-measurement, def:tau-dot-product-projector, def:indicator-vector, def:decoding-map, def:generalized-pauli}
	Since the measurement $\{\hat{S}_{g_X,g_Z}\}$ is projective (Lemma~\ref{lem:qld-4-7}) and the $\tau^X, \tau^Z$ observables are self-inverse,
	\[
		V_{\mathrm{A}} V_{\mathrm{A}}^\dagger = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \Id_{\mathrm{A}''} = \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''}\;,
	\]
	and the same computation gives $V_{\mathrm{A}}^\dagger V_{\mathrm{A}} = \Id$, so $V_{\mathrm{A}}$ is unitary; likewise $V_{\mathrm{B}}$. For \eqref{eq:v-swap-obs-conjugation}, conjugate the product form \eqref{eq:tildewj-product-form} of $\tilde{W}^j(\tilde{u})$ (Lemma~\ref{lem:tildew-product-form}): by the orthogonality of the projectors $\hat{S}_{g_X,g_Z}$, only the diagonal terms survive, and the twisted commutation relation (Lemma~\ref{lem:twisted-commutation})
	\[
		\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X)) \, \tau^W(e_j \tilde{u}) = (-1)^{\tr( e_j(\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \tau^W(e_j \tilde{u}) \, \tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))
	\]
	cancels the sign $(-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))}$ term by term, leaving $\sum_{g_X,g_Z} \hat{S}_{g_X,g_Z} \ot \tau^W(e_j \tilde{u}) = \Id \ot \tau^W(e_j \tilde{u})$. For \eqref{eq:qld-unitary-6}, expand $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ by \eqref{eq:tilde_M} and \eqref{eq:def-tauwu}; by the orthogonality of the $\hat{S}_{g_X,g_Z}$, conjugation replaces, in the term of $\hat{S}^W_g$, each projector $\tau^W_h$ by $\tau^W_{h + \mathrm{Dec}(g)}$, using the identities $\tau^X(s)\, \tau^Z_h \,\tau^X(s)^\dagger = \tau^Z_{h+s}$ and $\tau^Z(s)\, \tau^X_h\, \tau^Z(s)^\dagger = \tau^X_{h+s}$. Substituting $h' = h + \mathrm{Dec}(g)$ turns the constraint $h \cdot \mathrm{ind}_m(u) = (\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)) - a$ into $h' \cdot \mathrm{ind}_m(u) = -a = a$, since $\F_q$ has characteristic $2$; the quantity $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ cancels exactly, so no relation between it and $g(u)$ is used (Remark~\ref{rem:qld-decoding-identity}). Since $h' \cdot \mathrm{ind}_m(u) = g_{h'}(u)$ \eqref{eq:low-degree-encoding-definition}, summing over $g$ gives \eqref{eq:qld-unitary-6}; the computation for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ is identical.
\end{proof}

\begin{lemma}[Extraction of the EPR state and the Pauli observables]\label{lem:qld-unitary}
	\lean{MIPStarRE.QPBT.ExtractionWitness}
	\lean{MIPStarRE.QPBT.deltaExtract}
	\uses{lem:qld-4-7, def:v-swap-unitary, def:expanded-state, lem:projective-strategy-setup, def:generalized-pauli, def:EPR, def:povm-distance}
	There is a universal constant $C_{\mathrm{ext}}\geq1$. Set
	\[
		\delta_P^{\mathrm{ext}}=C_{\mathrm{ext}}B,
		\qquad
		\delta_{\mathrm{qld}}=C_{\mathrm{ext}}
		\left((\delta_P^{\mathrm{ext}})^{1/4}+\frac{md}{q}\right).
	\]
	There exist unitaries $V_{\mathrm{A}}$ acting on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ and $V_{\mathrm{B}}$ acting on registers $\mathrm{B}\mathrm{B}'\mathrm{B}''$, such that the following hold.
	\begin{enumerate}
		\item There exists a state $\ket{\mathrm{aux}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'$ such that
		\[
			\bigl\| V_{\mathrm{A}} \ot V_{\mathrm{B}} \ket{\hat{\psi}}_{\mathrm{A}\mathrm{A}'\mathrm{A}''\mathrm{B}\mathrm{B}'\mathrm{B}''} - \ket{\mathrm{aux}}_{\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A}''\mathrm{B}''} \bigr\|^2 \leq \delta_{\mathrm{qld}}\;.
		\]
		\item For $W \in \{X,Z\}$,
		\begin{align*}
			V_{\mathrm{A}} \, \bigl(M^{(\mathrm{Pauli},W)}_h \bigr)_{\mathrm{A}} \, V_{\mathrm{A}}^\dagger &\approx_{\delta_{\mathrm{qld}}} \Id_{\mathrm{A}\mathrm{A}'} \ot (\tau^W_h)_{\mathrm{A}''}\;, \\
			V_{\mathrm{B}} \, \bigl(M^{(\mathrm{Pauli},W)}_h \bigr)_{\mathrm{B}} \, V_{\mathrm{B}}^\dagger &\approx_{\delta_{\mathrm{qld}}} \Id_{\mathrm{B}\mathrm{B}'} \ot (\tau^W_h)_{\mathrm{B}''}\;,
		\end{align*}
		where the $\approx$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A}''\mathrm{B}''}$, with the answer summation over $h \in \F_q^{M}$ and no average over questions.
	\end{enumerate}
	The unitaries may be taken to be $V_{\mathrm{A}}$ and $V_{\mathrm{B}}$ of Definition~\ref{def:v-swap-unitary}.
	The conditional result below assumes the global polynomial-pair measurement
	of Lemma~\ref{lem:qld-4-7}, whereas the present proof obtains that measurement
	from the lemma. It therefore establishes the extraction conclusions only
	after the measurement and its consistency estimates are supplied, not the
	existence claim above. The missing composition and the range-projection
	transfer are recorded in \cite{gap:qpbt_extraction-transfer}.
\end{lemma}
\begin{proof}
	\uses{def:v-swap-unitary, lem:v-swap-conjugation, lem:tildew-product-form, lem:qld-construct-the-paulis, lem:qld-win-implications, fact:triangle-for-simeq, def:bracket, lem:cancellation, lem:schwartz-zippel-total-degree, lem:qld-4-7}
	For the first item, the self-consistency of the observables $\tilde{W}^j$ (Item~2 of Lemma~\ref{lem:qld-construct-the-paulis}) is equivalent, since these observables are Hermitian involutions (Lemma~\ref{lem:tildew-product-form}), to $\E_{j \in \{0,\ldots,t-1\}} \E_{\tilde{u} \in \F_q^M} \bra{\hat\psi} \tilde{W}^j(\tilde{u}) \ot \tilde{W}^j(\tilde{u}) \ket{\hat\psi} \geq 1 - \delta_P/2$; setting $\ket{\vartheta} = V_{\mathrm{A}} \ot V_{\mathrm{B}} \ket{\hat\psi}$ and using the exact conjugation identities of Lemma~\ref{lem:v-swap-conjugation}, this becomes $\bra{\vartheta} H_W \ket{\vartheta} \geq 1 - \delta_P/2$ for $W \in \{X,Z\}$, where $H_W = \E_j \E_{\tilde{u}} \, \tau^W(e_j \tilde{u}) \ot \tau^W(e_j \tilde{u}) = \bigl( \E_{s \in \F_q} \tau^W(s) \ot \tau^W(s) \bigr)^{\ot M}$ by the tensor factorization of $\tau^W(\tilde{u})$ and the invariance of the uniform average over $s$ under $s \mapsto e_j s$. By Lemma~\ref{lem:cancellation}, $\E_{s,s'} \tau^X(s)\tau^Z(s') \ot \tau^X(s)\tau^Z(s') = \ket{\mathrm{EPR}_q}\bra{\mathrm{EPR}_q}$ on each pair of qudits, whence $H_X H_Z = \ket{\mathrm{EPR}_q}\bra{\mathrm{EPR}_q}^{\ot M}$. The bounds $\| (\Id - H_W)\ket{\vartheta} \|^2 \leq \delta_P$ and $\bra{\vartheta} H_W^2 \ket{\vartheta} \geq 1 - 2\delta_P$, combined through the triangle inequality $\| H_X \ket{\vartheta} - H_Z \ket{\vartheta} \| \leq 2\sqrt{\delta_P}$ (see Remark~\ref{rem:qld-unitary-triangle-slip}), give $\bra{\vartheta} \Id_{\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'} \ot (\ket{\mathrm{EPR}_q}\bra{\mathrm{EPR}_q}^{\ot M})_{\mathrm{A}''\mathrm{B}''} \ket{\vartheta} \geq 1 - 4\delta_P$.
	% Case distinction added: the source normalizes the projected vector
	% without ensuring that it is nonzero; see Remark rem:qld-unitary-triangle-slip.
	If $\delta_P > 1/8$, then, after enlarging the universal constant in $\delta_{\mathrm{qld}}$, both items of the lemma hold with $\ket{\mathrm{aux}}$ an arbitrary unit state, since their left-hand sides never exceed $4$; assume therefore $\delta_P \leq 1/8$. Then the vector $(\bra{\mathrm{EPR}_q}^{\ot M})_{\mathrm{A}''\mathrm{B}''} \ket{\vartheta}$ has squared norm at least $1 - 4\delta_P \geq 1/2 > 0$, and $\ket{\mathrm{aux}}$ may be defined as its normalization; the overlap of $\ket{\vartheta}$ with $\ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M}$ equals the norm of that vector and is at least $\sqrt{1 - 4\delta_P} \geq 1 - 4\delta_P$, which yields the first item with a bound of $8\delta_P = O(\sqrt{\delta_P})$. For the second item, Lemma~\ref{lem:qld-win-implications} gives, on average over $u \in \F_q^m$, $M^{(\mathrm{Pauli},W)}_{[g_h(u)=a]} \ot \Id \simeq_\eps \Id \ot M^{(\mathrm{Point},W),u}_a$ and $\Id \ot M^{(\mathrm{Point},W),u}_a \simeq_\eps M^{(\mathrm{Point},W),u}_a \ot \Id$, where $M^{(\mathrm{Pauli},W)}_{[g_h(u)=a]} = \sum_{h : g_h(u) = a} M^{(\mathrm{Pauli},W)}_h$; combining these with Item~1 of Lemma~\ref{lem:qld-construct-the-paulis} by Lemma~\ref{fact:triangle-for-simeq}, using $\eps \leq \sqrt{\eps} \leq \delta_P$, yields $M^{(\mathrm{Pauli},W)}_{[g_h(u)=a]} \ot \Id \simeq_{\sqrt{\delta_P}} \Id \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a$. Writing $\ket{\Delta} = \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M}$, the quantity to be bounded for the $\mathrm{A}$-side relation equals $2 - 2\sum_h \bra{\Delta} V_{\mathrm{A}} M^{(\mathrm{Pauli},W)}_h V_{\mathrm{A}}^\dagger \ot (\tau^W_h)_{\mathrm{B}''} \ket{\Delta}$, since $(\tau^W_h)_{\mathrm{A}''} \ket{\mathrm{EPR}_q}^{\ot M} = (\tau^W_h)_{\mathrm{B}''} \ket{\mathrm{EPR}_q}^{\ot M}$. Replacing $(\tau^W_h)_{\mathrm{B}''}$ by the averaged coarse-graining $\E_u \sum_{h' : g_{h'}(u) = g_h(u)} (\tau^W_{h'})_{\mathrm{B}''}$ costs at most $md/q$ by Lemma~\ref{lem:schwartz-zippel-total-degree} (distinct $h \neq h'$ have distinct encodings $g_h \neq g_{h'}$, of total degree at most $md$), and by \eqref{eq:qld-unitary-6} the resulting sum equals $\E_u \sum_{a} \bra{\Delta} V_{\mathrm{A}} M^{(\mathrm{Pauli},W)}_{[g_h(u)=a]} V_{\mathrm{A}}^\dagger \ot V_{\mathrm{B}} \tilde{M}^{W,\mathrm{ind}_m(u)}_a V_{\mathrm{B}}^\dagger \ket{\Delta}$. Exchanging $\ket{\Delta}$ for $\ket{\vartheta}$ costs $O(\delta_P^{1/4})$ by the first item, and the resulting expression $\E_u \sum_a \bra{\hat\psi} M^{(\mathrm{Pauli},W)}_{[g_h(u)=a]} \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \ket{\hat\psi}$ is at least $1 - O(\sqrt{\delta_P})$ by the $\simeq_{\sqrt{\delta_P}}$ relation above. Altogether the distance is $O(\delta_P^{1/4} + md/q)$; the $\mathrm{B}$-side relation is proved identically.
\end{proof}

